import { GenerativeReport } from '$lib/database/schemas.js';

/**
 * Standalone referral letter (`referral_letter_en`), generated by the agent's
 * POST /workflows/referral-letter. Separate from the old `referral_en` variant,
 * which stays as the rollback path.
 *
 * The letter lives on whichever job it was generated on. Every comprehensive
 * dispatch creates a NEW job, so the latest job often has no letter: status and
 * download must look up the latest job that HAS one.
 */
export const REFERRAL_LETTER_KEY = 'referral_letter_en';
const LETTER_PATH = `sot.variants.${REFERRAL_LETTER_KEY}`;

// Parent states the agent refuses to dispatch against (a comprehensive run would
// replace the parent sot, letter included).
const BUSY_PARENT_STATES = ['generating', 'queued', 'pending'];

/** Latest job carrying a letter in any state, or null. */
export function findLetterJob(patientId, projection) {
	return GenerativeReport.findOne({ patientId, [LETTER_PATH]: { $exists: true } }, projection)
		.sort({ createdAt: -1 })
		.lean();
}

/**
 * Latest job the agent can build a letter from: it must hold the redacted case
 * snapshot (saved by the agent when a comprehensive run starts) and not be busy.
 */
export function findDispatchJob(patientId) {
	return GenerativeReport.findOne(
		{
			patientId,
			'sot.redactedCase': { $exists: true, $ne: null },
			status: { $nin: BUSY_PARENT_STATES }
		},
		{ jobId: 1, redCodeMap: 1 }
	)
		.sort({ createdAt: -1 })
		.lean();
}

/** Latest job of any kind; the parent for a letter when no job holds a snapshot. */
export function findLatestJob(patientId) {
	return GenerativeReport.findOne({ patientId }, { jobId: 1, status: 1, redCodeMap: 1 })
		.sort({ createdAt: -1 })
		.lean();
}

export const isBusyJob = (job) => BUSY_PARENT_STATES.includes(job?.status);

/**
 * Tokens are stable per (patient, value) (redCode.js stableCode), so a freshly
 * built map can only ADD entries to a job's map: existing tokens, and the
 * reports already de-tokenized with them, never change.
 */
export function mergeRedCodeMaps(existing = [], fresh = []) {
	const known = new Set((existing ?? []).map((e) => e.token));
	return [...(existing ?? []), ...(fresh ?? []).filter((e) => !known.has(e.token))];
}

/** Stored variant status → UI state. */
export function letterState(variant) {
	switch (variant?.status) {
		case 'successful':
		// A letter the agent saved as needs_review shows as ready; its
		// reviewWarnings stay in the database as the audit trail.
		case 'needs_review':
			return 'ready';
		case 'generating':
			return 'generating';
		case 'failed':
			return 'failed';
		default:
			return 'absent';
	}
}

import { deepReplace } from '../utils/anonymization/applyAnonymization.js';
import { forwardPairs } from '../utils/anonymization/redCode.js';

const NO_ENTRY = /^(none|n\/?a|no|unknown|not (reported|applicable)|-+)$/i;
const TITLE = /^(dr|dre|doctor|mr|ms|mrs|mx|miss)\b\.?\s*/i;

/**
 * `referral_metadata` for the letter's addressee (standard §3.1: the primary
 * physician from the autobiographical history, exactly as supplied). Returns
 * undefined when there is no usable entry ("Dr. n/a" included, §3.2), so the
 * letter keeps its placeholder.
 * @param {unknown} familyDoctor
 */
export function referringClinicianFrom(familyDoctor) {
	const name = typeof familyDoctor === 'string' ? familyDoctor.trim() : '';
	if (!name.replace(TITLE, '') || NO_ENTRY.test(name.replace(TITLE, ''))) return undefined;
	return { referringClinician: { name } };
}

/**
 * Standard §3.3 salutation from the (de-tokenized) addressee name: title and
 * surname when titled, the full name when not, the placeholder when absent.
 * Runs after token restoration because a token hides where the surname is.
 * @param {unknown} name
 */
export function salutationFor(name) {
	const n = typeof name === 'string' ? name.trim() : '';
	if (!n || n.startsWith('[')) return 'Dear Dr. [Referring clinician],';
	const title = n.match(TITLE)?.[0].trim();
	return title ? `Dear ${title} ${n.split(/\s+/).pop()},` : `Dear ${n},`;
}

/**
 * Tokenize the referrer with the job's redaction map. The name may only leave the
 * server as a token: if the patient's profile did not cover it, return undefined
 * (the letter keeps its placeholder) rather than send a provider's name in the clear.
 * @param {object | undefined} referralMetadata  output of referringClinicianFrom()
 * @param {Array<{find:string, token:string}>} redCodeMap
 */
export function tokenizeReferrer(referralMetadata, redCodeMap = []) {
	if (!referralMetadata) return undefined;
	const tokenized = deepReplace(referralMetadata, forwardPairs(redCodeMap));
	return /⟦[^⟧]+⟧/.test(tokenized?.referringClinician?.name ?? '') ? tokenized : undefined;
}
